// Robin keeps an apology balance: apology +1, insult -1, gift ignored; warm only if the balance is positive.
function visible(actions) {
  let balance = 0;
  for (const action of actions) {
    if (action === "apologise") balance += 1;
    else if (action === "insult") balance -= 1;
    // gift has no effect
  }
  return { mood: balance > 0 ? "warm" : "cold" };
}

// Robin keeps a benefit balance: apology +1, gift +1, insult -1; warm only if the balance is positive.
function visible(actions) {
  let balance = 0;
  for (const action of actions) {
    if (action === "apologise") balance += 1;
    else if (action === "gift") balance += 1;
    else if (action === "insult") balance -= 1;
  }
  return { mood: balance > 0 ? "warm" : "cold" };
}

// If Robin's first action is insult, Robin stays cold; otherwise Robin is cold only if two insults occur consecutively.
function visible(actions) {
  if (actions.length === 0) return { mood: "warm" };
  if (actions[0] === "insult") return { mood: "cold" };

  for (let i = 1; i < actions.length; i++) {
    if (actions[i] === "insult" && actions[i - 1] === "insult") {
      return { mood: "cold" };
    }
  }
  return { mood: "warm" };
}

// Robin starts with grudge 1; insults raise grudge, apologies lower it only while grudge is below 2, gifts do nothing; warm at grudge 0 or less.
function visible(actions) {
  let grudge = 1;

  for (const action of actions) {
    if (action === "insult") {
      grudge += 1;
    } else if (action === "apologise") {
      if (grudge < 2) {
        grudge -= 1;
        if (grudge < 0) grudge = 0;
      }
    }
    // gift has no effect
  }

  return { mood: grudge <= 0 ? "warm" : "cold" };
}

