// Explanation: Robin weights recent actions more, using insult -6, apology +3, gift +4, with each earlier action multiplied by 0.7.
function visible(actions) {
  let score = 0;
  for (let i = 0; i < actions.length; i++) {
    const w = Math.pow(0.7, actions.length - 1 - i);
    const a = actions[i];
    if (a === "insult") score -= 6 * w;
    else if (a === "apologise") score += 3 * w;
    else if (a === "gift") score += 4 * w;
  }
  return { mood: score > 0 ? "warm" : "cold" };
}

// Explanation: Robin tracks a running score; consecutive insults hurt extra, and a gift after two insults helps extra.
function visible(actions) {
  let score = 0;
  let prev1 = null;
  let prev2 = null;
  for (const a of actions) {
    if (a === "insult") {
      score -= 6;
      if (prev1 === "insult") score -= 1;
    } else if (a === "apologise") {
      score += 3;
    } else if (a === "gift") {
      score += 4;
      if (prev1 === "insult" && prev2 === "insult") score += 2;
    }
    prev2 = prev1;
    prev1 = a;
  }
  return { mood: score > 0 ? "warm" : "cold" };
}

